import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"安全启动链","description":"","frontmatter":{"title":"安全启动链","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/secure-boot-chain.md","filePath":"cs/secure-boot-chain.md","lastUpdated":1789023840000}'),p={name:"cs/secure-boot-chain.md"};function u(_,a,m,E,b,A){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="安全启动链" tabindex="-1">安全启动链 <a class="header-anchor" href="#安全启动链" aria-label="Permalink to &quot;安全启动链&quot;">​</a></h1><div class="epigraph"><p>安全启动从不可变的 ROM 锚开始，每一级只启动被上一签过的下一镜像。链断在固件更新、密钥管理或「为了方便关掉验证」。</p><footer>—— 据 UEFI Secure Boot；NIST SP 800-147；对照 Anderson 对启动完整性</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/remote-attestation">远程证明</a>把度量送给别人。缺口是<strong>本机启动路径</strong>必须先有度量。本课讲 ROM→固件→引导器→内核，不写绕过安全启动的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无链则 rootkit 可先于内核加载。UEFI 数据库、PK/KEK/db。缺口是更新与双启动的密钥管理。</p><h3 id="measured-boot" tabindex="-1">measured boot <a class="header-anchor" href="#measured-boot" aria-label="Permalink to &quot;measured boot&quot;">​</a></h3><p>度量启动把哈希写入 PCR，供证明；安全启动是拒绝未签镜像。二者可并存。</p><p><span class="marginnote">SP 800-147。禁止绕过教程。固件安全下一课把更新与植入当主题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画签名链。对照安全启动失败时的砖机风险。下一课固件。</p>',12)),(e(),n(h,null,{default:o(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROM%5B%22ROM%20%E9%94%9A%22%5D%20--%3E%20FW%5B%22%E5%9B%BA%E4%BB%B6%22%5D%0A%20%20FW%20--%3E%20LDR%5B%22%E5%BC%95%E5%AF%BC%E5%99%A8%22%5D%0A%20%20LDR%20--%3E%20OS%5B%22%E5%86%85%E6%A0%B8%22%5D%0A%20%20FW%20--%3E%20SIG%5B%22%E6%AF%8F%E7%BA%A7%E9%AA%8C%E7%AD%BE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>启动完整是后续 MAC/TEE 的前提。固件被改则链从根上烂。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写关闭验证。固件安全下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>证明假设启动度量诚实；安全启动守本地链。</li><li>ROM 锚到内核逐级验签。</li><li>更新与密钥是运营 TCB。</li><li>下一课固件安全。</li><li>出处：UEFI Secure Boot；NIST SP 800-147；Anderson。</li></ul>',8))])}const P=i(p,[["render",u]]);export{B as __pageData,P as default};
